  document.querySelector('[data-timer]')?.addEventListener('click', () => { if (timerId) { clearInterval(timerId); timerId = null; return; } const start = Date.now(); timerId = setInterval(() => { const clock = document.querySelector('#timer'); if (!clock) return clearInterval(timerId); const seconds = Math.floor((Date.now() - start) / 1000); clock.textContent = `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`; }, 250); });

  document.querySelectorAll('[data-nutrition-day]').forEach(button => button.onclick = () => mutate(state => state.nutrition.selectedDay = Number(button.dataset.nutritionDay)));
