  document.querySelector('[data-shop-list]')?.addEventListener('click', () => modal(`<p class="eyebrow">LISTA SEMANAL</p><h2>Compras base</h2><div class="shopping-list">${['Proteínas elegidas', 'Arroz, avena, papas y pan integral', 'Frutas y vegetales de la semana', 'Aceite, condimentos y básicos'].map(item => `<label><input type="checkbox"> ${item}</label>`).join('')}</div>`));
